fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "—"
    val seconds = exposureTimeNs.toDouble() / 1_000_000_000.0
    if (seconds >= 1.0) {
        return if (seconds == seconds.toLong().toDouble()) {
            "${seconds.toLong()}s"
        } else {
            String.format("%.1f", seconds).let { "${it}s" }
        }
    }
    val den = (1.0 / seconds).toInt().coerceAtLeast(1)
    return "1/${den}s"
}
```

