fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "—"
    val seconds = exposureTimeNs / 1_000_000_000.0
    if (seconds >= 1.0) {
        return if (seconds == kotlin.math.round(seconds).toInt().toDouble()) {
            "${seconds.toLong()}s"
        } else {
            "${String.format("%.1f", seconds)}s"
        }
    }
    val standardDenominators = intArrayOf(
        32000, 16000, 8000, 4000, 2000, 1000, 500, 250, 125, 60, 30, 15, 8, 4, 2
    )
    val exactDenominator = 1.0 / seconds
    val best = standardDenominators.minBy { kotlin.math.abs(it.toDouble() - exactDenominator) }
    return "1/${best}s"
}

